import{z as o,x as l,o as t,c as d,q as A,j as r,D as e,d as B,s as i,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"研究问题的起源","description":"","frontmatter":{"title":"研究问题的起源","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/research-question-origination.md","filePath":"quant/research-question-origination.md","lastUpdated":1791063341000}'),p={name:"quant/research-question-origination.md"};function C(h,E,u,F,D,m){const n=l("Mermaid");return t(),d("div",null,[E[2]||(E[2]=A('<h1 id="研究问题的起源" tabindex="-1">研究问题的起源 <a class="header-anchor" href="#研究问题的起源" aria-label="Permalink to &quot;研究问题的起源&quot;">​</a></h1><div class="epigraph"><p>「市场有效」从来不能被单独检验：它总是和一个具体的定价模型绑在一起被检验。所以每一个异象都同时是两个问题——市场的问题，和模型的问题。</p><footer>—— 据 Roll (1977) 对资产定价检验联合假设的表述；Fama (1998) 的回应整理</footer></div><p><a href="/quant/simulator-impact-bias">上一课</a>把 RL 课序收束在冲击模拟器上：校准支撑外的量必须凸化或截断动作，评估环境不得弱于训练环境。那根主线保护的是「答案」这一端——不许环境送免费的分。本课是「从问题到组合」的第一课，把注意力挪回「问题」这一端：一次量化研究的起点不是数据集，而是一个能被拒绝的问题。后课默认你已经带着这样的问题进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>市场每天把观察免费送到你面前：<a href="/quant/seasonality-anomalies">季节性与日历异象</a>的日历效应、彩票型的极端收益溢价、<a href="/quant/flash-crash-2010">2010 闪电崩盘</a>这样的微观结构事件、<a href="/quant/index-rebalance">指数调入调出</a>的流量冲击。观察不缺，缺的是把观察变成<strong>可检验问题</strong>的那一步。研究大多死在开始而不是结尾：数据窥探从选题就开始了——选择检验哪条规律，本身已经花掉一次试验（Lo and MacKinlay 1990）；<a href="/quant/backtest-overfitting">过拟合次数与试错</a>把这笔账算在 Sharpe 上，而选题时的隐性试错不进任何台账。</p><p>好问题有三个判据。其一，<strong>经济逻辑</strong>：回答「谁把钱留在桌上、为何套利者不搬走」；信息有成本、注意力有限、机构受约束都是正经答案，「历史数据里它出现过」不是。其二，<strong>可证伪</strong>：预先写出拒绝条件——若观察到什么，这个问题就死。其三，<strong>成本可行</strong>：信号强度扣掉交易成本与容量后还剩什么；统计显著与经济显著是两道门，<a href="/quant/econ-vs-stat-sig">经济显著性 vs 统计显著性</a>已经分开过。</p><p><span class="marginnote">「可证伪」是波普尔的标准：一个命题只有可能被证据推翻，才算科学命题。「明天的涨跌谁也说不准」这类怎么说都对的话，恰恰因为不可能错而没有信息量。写拒绝条件，就是把「怎么说都对」变成「观察到什么我就认输」——认输条款越具体，问题越值钱。</span></p><h3 id="用三个判据过一遍-pead" tabindex="-1">用三个判据过一遍 PEAD <a class="header-anchor" href="#用三个判据过一遍-pead" aria-label="Permalink to &quot;用三个判据过一遍 PEAD&quot;">​</a></h3><p>本单元全程用同一个案例：盈利公告后的价格漂移。观察是 Ball 与 Brown 1968 年就量过的现象：盈利意外为正，公告后收益继续偏正。经济逻辑：投资者消化信息慢、机构受约束；可证伪：若意外最高组的后续收益不再系统性高于最低组，假设死；成本可行：季度级换手。三道全过才立项。</p><p><span class="marginnote">McLean 与 Pontiff 给异象衰减定了价：可预测性样本外衰减约四分之一，发表后衰减过半。选题时就要假设——你想到的问题，别人也想到了。</span></p><p><span class="marginnote">数字实例（成本可行怎么算）：PEAD 季度换手约 4 轮，单边成本按 15 个基点，一个来回吃 0.3%，一年 4 轮合计约 1.2%；若公告后漂移年化约 6%，扣完还剩约 4.8%——这才叫「扣费后仍有余量」。不代入数字，成本可行就只是「感觉能活」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把观察写成一句固定句式的假设：对（对象与事件），若市场对（信息）反应不足或过度，则（方向与组合构造）在（期限）内应有可区分的收益差异；若不出现，假设被拒绝。拒绝条件写在句子里，不留到事后。三个判据变成三道闸：</p>',13)),(t(),r(s,null,{default:e(()=>[i(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBS%5B%22%E5%B8%82%E5%9C%BA%E8%A7%82%E5%AF%9F%EF%BC%9A%E5%BC%82%E8%B1%A1%20%2F%20%E5%88%B6%E5%BA%A6%E5%8F%98%E5%8C%96%20%2F%20%E5%BE%AE%E8%A7%82%E7%BB%93%E6%9E%84%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20G1%7B%22%E7%BB%8F%E6%B5%8E%E9%80%BB%E8%BE%91%EF%BC%9A%E8%B0%81%E7%95%99%E9%92%B1%E3%80%81%E4%B8%BA%E4%BD%95%E6%B2%A1%E8%A2%AB%E6%90%AC%E8%B5%B0%22%7D%0A%20%20G1%20--%3E%7C%E8%BF%87%7C%20G2%7B%22%E5%8F%AF%E8%AF%81%E4%BC%AA%EF%BC%9A%E6%8B%92%E7%BB%9D%E6%9D%A1%E4%BB%B6%E5%B7%B2%E5%86%99%E5%87%BA%22%7D%0A%20%20G2%20--%3E%7C%E8%BF%87%7C%20G3%7B%22%E6%88%90%E6%9C%AC%E5%8F%AF%E8%A1%8C%EF%BC%9A%E6%89%A3%E8%B4%B9%E5%90%8E%E4%BB%8D%E6%9C%89%E4%BD%99%E9%87%8F%22%7D%0A%20%20G3%20--%3E%7C%E8%BF%87%7C%20LEDGER%5B%22%E5%86%99%E5%85%A5%E9%97%AE%E9%A2%98%E5%8F%B0%E8%B4%A6%EF%BC%8C%E7%AB%8B%E9%A1%B9%22%5D%0A%20%20G1%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20PARK%5B%22%E6%90%81%E7%BD%AE%EF%BC%9A%E8%AE%B0%E5%85%A5%E8%B4%9F%E6%B8%85%E5%8D%95%22%5D%0A%20%20G2%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20PARK%0A%20%20G3%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20PARK%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[B("立项输出两样东西：一句带拒绝条件的假设，一条台账记录。台账制度在"),a("a",{href:"/quant/research-log-discipline"},"研究日志与纪律"),B("里已经立过，本课第一次喂给它内容。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"三个判据各挡住一类典型的死法。经济逻辑挡「数据里的巧合」：没有机制的问题，机制环境一变，规律没有理由留下；Grossman 与 Stiglitz 的道理——信息完全有效则无人有动机研究，可研究的问题必然伴随成本或约束。可证伪挡「不可错的问题」：把任何结果都解释成支持的研究无法积累知识；且检验失败杀掉的是「假设＋定价模型」这一对，不是市场本身。成本可行挡「纸上异象」：扣不掉成本的可预测性不是研究问题，只是回测统计量。",-1)),E[6]||(E[6]=a("p",null,"「联合假设」决定了拒绝之后怀疑谁的顺序：",-1)),(t(),r(s,null,{default:e(()=>[i(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%81%87%E8%AE%BE%EF%BC%9A%E5%85%AC%E5%91%8A%E5%90%8E%E6%BC%82%E7%A7%BB%E5%AD%98%E5%9C%A8%22%5D%20--%3E%20PAIR%5B%22%E6%A3%80%E9%AA%8C%E5%AF%B9%E8%B1%A1%20%3D%20%E5%81%87%E8%AE%BE%20%2B%20%E5%AE%9A%E4%BB%B7%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20M%5B%22%E5%AE%9A%E4%BB%B7%E6%A8%A1%E5%9E%8B%EF%BC%9A%E5%9F%BA%E5%87%86%E6%94%B6%E7%9B%8A%E6%80%8E%E4%B9%88%E7%AE%97%22%5D%20--%3E%20PAIR%0A%20%20PAIR%20--%3E%20T%7B%22%E6%8B%92%E7%BB%9D%E6%9D%A1%E4%BB%B6%E8%A7%A6%E5%8F%91%EF%BC%9F%22%7D%0A%20%20T%20--%3E%7C%22%E6%98%AF%22%7C%20R%5B%22%E5%81%87%E8%AE%BE%E4%B8%8E%E6%A8%A1%E5%9E%8B%E8%BF%99%E4%B8%80%E5%AF%B9%E8%A2%AB%E6%8B%92%22%5D%0A%20%20R%20--%3E%20Q%7B%22%E5%85%88%E6%80%80%E7%96%91%E8%B0%81%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%9C%BA%E5%88%B6%E6%9C%89%E6%8D%AE%22%7C%20SUSM%5B%22%E6%80%80%E7%96%91%E6%A8%A1%E5%9E%8B%EF%BC%9A%E5%9F%BA%E5%87%86%E4%B8%8E%E9%A3%8E%E9%99%A9%E8%B0%83%E6%95%B4%22%5D%0A%20%20Q%20--%3E%7C%22%E6%9C%BA%E5%88%B6%E7%AB%99%E4%B8%8D%E4%BD%8F%22%7C%20SUSH%5B%22%E6%80%80%E7%96%91%E5%81%87%E8%AE%BE%E6%9C%AC%E8%BA%AB%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=A('<p><span class="marginnote">「联合假设」是说：你检验「漂移存在」时，永远同时假定了「基准收益算得对」。像用验钞机验出一张假钞——你分不清是钞票假还是验钞机坏了。一次拒绝只能说明两者至少其一有问题，单独给「市场无效」或「模型失灵」定罪，都超出了证据允许的范围。</span></p><p>三个判据是过滤而非打分。被搁置的问题进负清单，它与正面结果一样是资产：防止同一个观察半年后被当作新想法再挖一遍。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只解决「问题是否够格被回答」，不管「是否为真」。微观结构事件类问题往往制度特定，拒绝条件要写成「在此制度下」；异象类要防联合假设的另一种误用——别把模型的失败全推给市场。也不要把选题与信号挖掘混为一谈：对既有信号换参数重跑，归<a href="/quant/multiple-testing-factors">多重检验与 p-hacking</a> 管辖。问题立项之后仍只是纸面合同；下一课把合同锁死在碰数据之前。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>研究的起点是可被拒绝的问题，不是数据集；数据窥探从选题计次。</li><li>三个判据：经济逻辑（谁留钱、为何没被搬走）、可证伪（拒绝条件写进句子）、成本可行（扣费后有余量）。</li><li>被搁置的问题进负清单；负清单是防止重复挖掘的资产。</li><li>检验失败杀掉的是假设与定价模型这一对，不要单独给市场定罪。</li><li>本单元后续各课以盈利公告后漂移为全程案例。</li><li>出处：Roll (1977) 与 Fama (1998) 的联合假设口径；Grossman and Stiglitz (1980)；Lo and MacKinlay (1990)；McLean and Pontiff (2016)；Ball and Brown (1968)。</li></ul>',6))])}const g=o(p,[["render",C]]);export{c as __pageData,g as default};
